@ExtendWith(MockitoExtension.class)
class OrderServiceTest {

    @Mock
    private PaymentGateway paymentGateway;

    @Mock
    private OrderRepository orderRepository;

    @InjectMocks
    private OrderServiceImpl orderService;

    @Captor
    private ArgumentCaptor<OrderEntity> orderCaptor;

    @Test
    void shouldProcessOrderSuccessfully() {
        OrderRequest request = new OrderRequest("item-123", 2, 99.99);
        OrderEntity savedEntity = new OrderEntity("ORD-999", "item-123", 2);

        when(paymentGateway.charge(anyString(), anyDouble())).thenReturn(true);
        when(orderRepository.save(any(OrderEntity.class))).thenReturn(savedEntity);

        OrderResponse response = orderService.processOrder(request);

        assertNotNull(response);
        assertEquals("ORD-999", response.getOrderId());

        verify(paymentGateway).charge(eq("item-123"), eq(199.98));
        verify(orderRepository).save(orderCaptor.capture());

        OrderEntity capturedOrder = orderCaptor.getValue();
        assertEquals("item-123", capturedOrder.getItemId());
        assertEquals(2, capturedOrder.getQuantity());
    }
}
